package com.leetcode.backend.service;
import com.leetcode.backend.model.*; import com.leetcode.backend.repository.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.security.SecureRandom; import java.time.LocalDateTime; import java.util.*;
@Service public class AssessmentCreatorService {
 private static final Set<String> VERIFICATION_PROOF_TYPES=Set.of("Certificate of incorporation","Business licence or trade certificate","Tax registration certificate (redacted)","Official organization letter","Accreditation or affiliation certificate","Passport","Aadhaar (redacted)","Other organization proof"); private final UserRepository users; private final AssessmentCreatorApplicationRepository applications; private final AssessmentCreatorDocumentRepository documents; private final AssessmentCreatorReviewAuditRepository audits; private final VerificationDocumentStorage storage; private final PasswordEncoder encoder; private final ApplicationEventPublisher publisher; private final SecureRandom random=new SecureRandom();
 public AssessmentCreatorService(UserRepository u,AssessmentCreatorApplicationRepository a,AssessmentCreatorDocumentRepository d,AssessmentCreatorReviewAuditRepository ar,VerificationDocumentStorage s,PasswordEncoder e,ApplicationEventPublisher p){users=u;applications=a;documents=d;audits=ar;storage=s;encoder=e;publisher=p;}
@Transactional public Map<String,Object> apply(String username,String fullName,String organization,String roleTitle,String purpose,String website,String organizationEmail,String intendedUse,String country,String documentType,MultipartFile file){User user=user(username);if(!user.isEmailVerified())throw new EmailNotVerifiedException("Verify your account email before requesting creator access.");applications.findTopByUserIdOrderByIdDesc(user.getId()).filter(a->Set.of(AssessmentEnums.CreatorStatus.EMAIL_OTP_PENDING,AssessmentEnums.CreatorStatus.PENDING_ADMIN_REVIEW,AssessmentEnums.CreatorStatus.APPROVED).contains(a.getStatus())).ifPresent(a->{throw new IllegalArgumentException("An active creator application already exists.");});String proof=clean(documentType,60);if(!VERIFICATION_PROOF_TYPES.contains(proof))throw new IllegalArgumentException("Choose an accepted verification proof type.");var stored=storage.store(file);AssessmentCreatorApplication app=new AssessmentCreatorApplication();app.setUser(user);app.setFullName(clean(fullName,120));app.setOrganization(clean(organization,160));app.setRoleTitle(clean(roleTitle,120));app.setPurpose(clean(purpose,160));app.setWebsite(optional(website,300));app.setOrganizationEmail(optional(organizationEmail,150));app.setIntendedUse(clean(intendedUse,3000));app.setCountry(clean(country,80));app.setDocumentType(proof);String otp=String.format("%06d",random.nextInt(1_000_000));app.setOtpHash(encoder.encode(otp));app.setOtpExpiresAt(LocalDateTime.now().plusMinutes(10));app.setOtpLastSentAt(LocalDateTime.now());applications.save(app);AssessmentCreatorDocument doc=new AssessmentCreatorDocument();doc.setApplication(app);doc.setStorageName(stored.name());doc.setOriginalName(stored.originalName());doc.setContentType(stored.contentType());doc.setSize(stored.size());documents.save(doc);publisher.publishEvent(new EmailNotificationEvents.CreatorOtpIssued(user.getEmail(),user.getUsername(),otp));return response(app);}
 @Transactional public Map<String,Object> verify(String username,Long id,String code){AssessmentCreatorApplication app=owned(username,id);if(app.getStatus()!=AssessmentEnums.CreatorStatus.EMAIL_OTP_PENDING)throw new IllegalArgumentException("This application is not awaiting an OTP.");if(app.getOtpExpiresAt().isBefore(LocalDateTime.now()))throw new OtpVerificationException("The code has expired.");if(app.getOtpAttempts()>=5)throw new OtpVerificationException("Too many incorrect attempts. Request a new code.");app.setOtpAttempts(app.getOtpAttempts()+1);if(!encoder.matches(code,app.getOtpHash()))throw new OtpVerificationException("The verification code is incorrect.");app.setOtpHash(null);app.setOtpExpiresAt(null);app.setStatus(AssessmentEnums.CreatorStatus.PENDING_ADMIN_REVIEW);app.setSubmittedAt(LocalDateTime.now());return response(applications.save(app));}
 @Transactional public void resend(String username,Long id){AssessmentCreatorApplication app=owned(username,id);if(app.getStatus()!=AssessmentEnums.CreatorStatus.EMAIL_OTP_PENDING)throw new IllegalArgumentException("This application is not awaiting an OTP.");if(app.getOtpLastSentAt()!=null&&app.getOtpLastSentAt().isAfter(LocalDateTime.now().minusSeconds(60)))throw new IllegalArgumentException("Wait before requesting another code.");String otp=String.format("%06d",random.nextInt(1_000_000));app.setOtpHash(encoder.encode(otp));app.setOtpExpiresAt(LocalDateTime.now().plusMinutes(10));app.setOtpAttempts(0);app.setOtpLastSentAt(LocalDateTime.now());publisher.publishEvent(new EmailNotificationEvents.CreatorOtpIssued(app.getUser().getEmail(),app.getUser().getUsername(),otp));}
 @Transactional(readOnly=true) public Map<String,Object> status(String username){User user=user(username);return applications.findTopByUserIdOrderByIdDesc(user.getId()).map(this::response).orElse(Map.of("status","NONE","approved",false));}
 @Transactional(readOnly=true) public boolean approved(User user){return applications.existsByUserIdAndStatus(user.getId(),AssessmentEnums.CreatorStatus.APPROVED);}
 public void requireApproved(User user){if(!approved(user))throw new AccessDeniedException("Approved Assessment Creator access is required.");}
 @Transactional(readOnly=true) public List<Map<String,Object>> adminList(String status){AssessmentEnums.CreatorStatus s=AssessmentEnums.CreatorStatus.valueOf(status.toUpperCase(Locale.ROOT));return applications.findByStatusOrderBySubmittedAtAsc(s).stream().map(this::response).toList();}
 @Transactional public Map<String,Object> decide(String adminName,Long id,AssessmentEnums.CreatorStatus next,String reason){User admin=user(adminName);AssessmentCreatorApplication app=applications.findById(id).orElseThrow(()->new RuntimeException("Application not found."));var previous=app.getStatus();boolean allowed=(next==AssessmentEnums.CreatorStatus.APPROVED||next==AssessmentEnums.CreatorStatus.REJECTED)&&previous==AssessmentEnums.CreatorStatus.PENDING_ADMIN_REVIEW||next==AssessmentEnums.CreatorStatus.REVOKED&&previous==AssessmentEnums.CreatorStatus.APPROVED;if(!allowed)throw new IllegalArgumentException("Invalid application status transition.");if(next==AssessmentEnums.CreatorStatus.REJECTED&&(reason==null||reason.isBlank()))throw new IllegalArgumentException("A rejection reason is required.");app.setStatus(next);app.setDecisionReason(optional(reason,500));app.setDecidedAt(LocalDateTime.now());applications.save(app);AssessmentCreatorReviewAudit audit=new AssessmentCreatorReviewAudit();audit.setActor(admin);audit.setApplication(app);audit.setPreviousStatus(previous);audit.setNewStatus(next);audit.setReason(app.getDecisionReason());audits.save(audit);publisher.publishEvent(new EmailNotificationEvents.CreatorDecision(app.getUser().getEmail(),app.getUser().getUsername(),next==AssessmentEnums.CreatorStatus.APPROVED,app.getDecisionReason()));return response(app);}
 @Transactional(readOnly=true) public DocumentContent document(Long appId){AssessmentCreatorDocument doc=documents.findByApplicationId(appId).orElseThrow(()->new RuntimeException("Document not found."));return new DocumentContent(storage.read(doc.getStorageName()),doc.getContentType(),doc.getOriginalName());} public record DocumentContent(byte[] bytes,String type,String name){}
 @Transactional public void purgeExpiredDocuments(int retentionDays){LocalDateTime cutoff=LocalDateTime.now().minusDays(retentionDays);for(AssessmentCreatorDocument doc:documents.findAll()){var app=doc.getApplication();if(doc.getDeletedAt()==null&&app.getDecidedAt()!=null&&app.getDecidedAt().isBefore(cutoff)){storage.delete(doc.getStorageName());doc.setDeletedAt(LocalDateTime.now());}}}
 private AssessmentCreatorApplication owned(String name,Long id){AssessmentCreatorApplication app=applications.findById(id).orElseThrow(()->new RuntimeException("Application not found."));if(!app.getUser().getUsername().equals(name))throw new AccessDeniedException("This application does not belong to you.");return app;} private User user(String n){return users.findByUsername(n).orElseThrow(()->new RuntimeException("Authenticated user not found."));} private String clean(String s,int max){if(s==null||s.isBlank())throw new IllegalArgumentException("Required application fields cannot be blank.");String value=s.trim().replaceAll("<[^>]*>","");if(value.length()>max)throw new IllegalArgumentException("An application field is too long.");return value;} private String optional(String s,int max){return s==null||s.isBlank()?null:clean(s,max);}
 private Map<String,Object> response(AssessmentCreatorApplication a){Map<String,Object> r=new LinkedHashMap<>();r.put("id",a.getId());r.put("status",a.getStatus());r.put("approved",a.getStatus()==AssessmentEnums.CreatorStatus.APPROVED);r.put("applicant",a.getUser().getUsername());r.put("email",a.getUser().getEmail());r.put("fullName",a.getFullName());r.put("organization",a.getOrganization());r.put("role",a.getRoleTitle());r.put("purpose",a.getPurpose());r.put("website",a.getWebsite());r.put("organizationEmail",a.getOrganizationEmail());r.put("intendedUse",a.getIntendedUse());r.put("country",a.getCountry());r.put("documentType",a.getDocumentType());r.put("submittedAt",a.getSubmittedAt());r.put("decisionReason",a.getDecisionReason());return r;}
}
